const raw = $input.first().json || {};
const body = (raw.body && typeof raw.body === 'object') ? raw.body : raw;
const email = String(body.email || '').trim();
if (!email) {
  throw new Error('Forgot-password webhook is missing email. Laravel must POST JSON with an email field.');
}
const message = body.message || '';
if (!message) {
  throw new Error('Forgot-password webhook is missing message HTML.');
}
const fromEmail = String(body.from_email || '').trim();
if (!fromEmail) {
  throw new Error('Forgot-password webhook is missing from_email. It must be the Gmail address that owns the n8n SMTP credential.');
}
return [{
  json: {
    email,
    subject: body.subject || 'Your TechHRM temporary password',
    message,
    from_name: body.from_name || 'TechHRM WSPO',
    from_email: fromEmail,
  },
}];
